package net.officefloor.hq.app.claim;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Opens the selected claims in list order (people in the order they were added, newest claim first
 * within a person), numbering each as it opens and auditing it as a single open would be. A selected
 * claim that cannot be opened (not DRAFT, its due-by inside a closed period, the user's role may not open, its note is empty while its due is above the note threshold, its person is flagged and the user is not a steward, or its person already has as many OPEN or PENDING claims in its period as the period's cap) is left as it is and counted
 * as refused; so is a selected id that is not a claim on the sheet. A claim whose due is above the review threshold goes to
 * REVIEW instead and counts as opened.
 */
public class BulkOpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
            Claims claims, People people, Periods periods, Settings settings, Sheets sheets, Rates rates, ClaimNumbering numbering, Rollup rollup, Audit audit, ClaimLog log,
            ObjectResponse<BulkOpenResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        List<Claim> all = claims.list(sheetId);
        // A role the sheet's open permission does not allow opens none of them.
        boolean allowed = settings.allows(sheetId, request.user(), "open");
        boolean steward = Settings.STEWARD.equals(settings.role(sheetId, request.user()));
        int opened = 0;
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                if (!allowed || !claim.getStatus().canBecome(ClaimStatus.OPEN)
                        || periods.isClosed(sheetId, claim.getPeriodDate())) {
                    continue;
                }
                java.math.RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId), on -> settings.roundingMode(sheetId, on));
                try {
                    ApplyClaimStatus.refuseFlagged(claim, sheets, people, steward);
                    ApplyClaimStatus.refuseNoteless(claim, sheets, people, rates, settings, rounding);
                    ApplyClaimStatus.refuseOverCap(claim, periods, all);
                } catch (ClaimStatusRefusedException e) {
                    continue;
                }
                if (ApplyClaimStatus.needsReview(claim, sheets, people, rates, settings, rounding)) {
                    // Above the review threshold it goes to REVIEW, unnumbered, and counts as opened.
                    claim.setOpenedBy(request.user());
                    claim.setStatus(ClaimStatus.REVIEW);
                    claims.save(claim);
                    log.record(claim, person, request.user());
                    audit.recordOnCommit(ClaimAudit.line("CLAIM_REVIEW", request.user(), person, claim, null));
                    opened++;
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                claim.setNumber(numbering.next(sheetId, claim.getPeriodDate()));
                claim.setOpenedBy(request.user());
                claim.setStatus(ClaimStatus.OPEN);
                claims.save(claim);
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.line("CLAIM_OPENED", request.user(), person, claim, claim.getNumber()));
                rollup.recordChanges(sheetId, request.user(), before);
                opened++;
            }
        }
        response.send(new BulkOpenResponse(opened, selected.size() - opened));
    }
}
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
import { createContext, useContext, useState, type ReactNode } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { claimsKey, settleBatchKey, useLastSettleBatch } from './useClaims';
import { peopleKey, usePeople } from '../people/usePeople';

type Selection = { selected: Set<string>; toggle: (id: string, on: boolean) => void; clear: () => void };

const SelectionContext = createContext<Selection | null>(null);

/** The claims ticked with their select checkbox, shared by every claim row and the bulk buttons. */
export function ClaimSelection({ children }: { children: ReactNode }) {
  const [selected, setSelected] = useState<Set<string>>(() => new Set());
  const toggle = (id: string, on: boolean) =>
    setSelected((was) => {
      const next = new Set(was);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  const clear = () => setSelected(new Set());
  return <SelectionContext.Provider value={{ selected, toggle, clear }}>{children}</SelectionContext.Provider>;
}

export function useClaimSelection(): Selection {
  const selection = useContext(SelectionContext);
  if (!selection) throw new Error('useClaimSelection outside ClaimSelection');
  return selection;
}

/** A claim row's select checkbox. */
export function ClaimSelect({ claimId }: { claimId: string }) {
  const { selected, toggle } = useClaimSelection();
  return (
    <input
      type="checkbox"
      data-testid="claim-select"
      checked={selected.has(claimId)}
      onChange={(e) => toggle(claimId, e.target.checked)}
    />
  );
}

// Opens the selected claims together: the server opens and numbers each that can be opened, in list
// order (people in the order they were added, newest claim first within a person), and leaves each
// that cannot as it is. Then shows how many were opened and how many were refused, and clears the
// selection; pressing again removes the old counts until the new ones are in.
export function BulkOpenButton() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const { selected, clear } = useClaimSelection();

  const open = useMutation({
    mutationFn: (claimIds: string[]) =>
      postJson<{ opened: number; refused: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/bulk-open`,
        { claimIds, user },
      ),
    onSuccess: () => {
      clear();
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-open"
        onClick={() => {
          open.reset();
          const ids = [...selected];
          once(() => open.mutateAsync(ids));
        }}
      >
        Open selected
      </button>
      {open.isSuccess && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{open.data.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{open.data.refused}</span>
        </>
      )}
      {open.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}
          The selected claims could not be opened.
        </span>
      )}
    </p>
  );
}

// Settles the selected claims together: the server settles each by the rules of settling one claim, in
// list order, by the signed-in user; a claim sent to PENDING counts as settled, one that cannot be
// settled is left as it is. Then shows how many were settled and how many were refused, and clears
// the selection; pressing again removes the old counts until the new ones are in. Beside it, the number of the
// sheet's last batch: a bulk settle that settled at least one claim.
export function BulkSettleButton() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const { selected, clear } = useClaimSelection();
  const lastBatch = useLastSettleBatch(sheet);

  const settle = useMutation({
    mutationFn: (claimIds: string[]) =>
      postJson<{ settled: number; refused: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/bulk-settle`,
        { claimIds, user },
      ),
    onSuccess: () => {
      clear();
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: settleBatchKey(sheet) }),
      ]);
    },
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-settle"
        onClick={() => {
          settle.reset();
          const ids = [...selected];
          once(() => settle.mutateAsync(ids));
        }}
      >
        Settle selected
      </button>{' '}
      Last batch <span data-testid="bulk-settle-batch">{lastBatch}</span>
      {settle.isSuccess && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{settle.data.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{settle.data.refused}</span>
        </>
      )}
      {settle.isError && (
        <span data-testid="bulk-settle-error" role="alert">
          {' '}
          The selected claims could not be settled.
        </span>
      )}
    </p>
  );
}

// Moves the selected claims to the chosen person together: the server moves each by the rules of moving one claim,
// in list order, by the signed-in user, and leaves each that cannot move as it is. Then shows how many were moved
// and how many were refused, and clears the selection; pressing again removes the old counts until the new ones are in.
export function BulkReassignButton() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const people = usePeople(sheet);
  const { selected, clear } = useClaimSelection();
  const [toPersonId, setToPersonId] = useState('');

  const reassign = useMutation({
    mutationFn: ({ claimIds, to }: { claimIds: string[]; to: string }) =>
      postJson<{ reassigned: number; refused: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/bulk-reassign`,
        { claimIds, toPersonId: to, user },
      ),
    onSuccess: () => {
      clear();
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });

  return (
    <p>
      <select
        data-testid="bulk-reassign-to"
        value={toPersonId}
        onChange={(e) => {
          reassign.reset();
          setToPersonId(e.target.value);
        }}
      >
        <option value="">Move to…</option>
        {people.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
